/* ================= 1. KHUTBAH IDUL FITRI (10 Topik) ================= */
window.KONTEN["Khutbah Idul Fitri"] = {
  sebutan: "Khutbah",
  bab: [
    {
      judul: "1. Etika Bermedia Sosial di Hari Raya",
      isi: [
        { ar: "أَمَّا بَعْدُ، فَيَا أَيُّهَا الْحَاضِرُوْنَ، إِنَّ يَوْمَ الْعِيْدِ هُوَ يَوْمُ الْفَرَحِ وَالسُّرُوْرِ، وَلَكِنْ عَلَيْنَا أَنْ نَحْذَرَ مِنَ الْمُبَالَغَةِ فِي التَّصْوِيْرِ وَنَشْرِهَا فِي وَسَائِلِ التَّوَاصُلِ الاجْتِمَاعِيِّ حَتَّى لَا نَقَعَ فِي الرِّيَاءِ وَالْعُجْبِ. إِنَّ الْمُسْلِمَ يَجِبُ أَنْ يَكُوْنَ قَلْبُهُ نَظِيْفًا مِنَ الْحَسَدِ وَالرِّيَاءِ.", tr: "Khutbah 1: Wahai hadirin, hari raya adalah hari kebahagiaan. Namun kita harus berhati-hati dari sikap berlebihan dalam memotret dan mengunggahnya di media sosial agar tidak terjerumus ke dalam sifat pamer (riya) dan bangga diri (ujub). Seorang muslim haruslah bersih hatinya dari rasa iri dan pamer." },
        { ar: "أَلَا إِنَّ اللَّهَ يُحِبُّ التَّوَاضُعَ وَيُبْغِضُ الْكِبْرَ. فَلْنَحْفَظْ أَلْسِنَتَنَا وَأَصَابِعَنَا مِنْ إِيْذَاءِ النَّاسِ، وَلْنَجْعَلْ يَوْمَ الْعِيْدِ هَذَا وَسِيْلَةً لِلتَّقَرُّبِ إِلَى اللَّهِ وَصِلَةِ الْأَرْحَامِ لَا لِلتَّفَاخُرِ بِالْأَمْوَالِ.", tr: "Khutbah 2: Ketahuilah, Allah mencintai kerendahan hati dan membenci kesombongan. Mari kita jaga lisan dan jari-jari kita dari menyakiti orang lain. Jadikanlah hari raya ini sebagai sarana mendekatkan diri kepada Allah dan menyambung silaturahmi, bukan untuk saling membanggakan harta." }
      ]
    },
    {
      judul: "2. Moderasi Beragama dan Toleransi",
      isi: [
        { ar: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ لِلَّهِ شُهَدَاءَ بِالْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَىٰ أَلَّا تَعْدِلُوا ۚ اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَىٰ. إِنَّ الْإِسْلَامَ دِيْنُ الْوَسَطِيَّةِ وَالِاعْتِدَالِ، لَا غُلُوَّ فِيْهِ وَلَا تَقْصِيْرَ.", tr: "Khutbah 1: Hai orang-orang yang beriman, jadilah kamu penegak kebenaran karena Allah, menjadi saksi dengan adil. Janganlah kebencianmu terhadap suatu kaum mendorong kamu untuk berlaku tidak adil. Islam adalah agama moderat dan seimbang, tidak berlebih-lebihan dan tidak pula mengurangi." },
        { ar: "فِيْ مُجْتَمَعِنَا الْمُتَنَوِّعِ، عَلَيْنَا أَنْ نُظْهِرَ سَمَاحَةَ الْإِسْلَامِ وَالتَّعَايُشَ السِّلْمِيَّ مَعَ كَافَّةِ النَّاسِ، مَعَ الْحِفَاظِ عَلَى عَقِيْدَتِنَا وَهُوِيَّتِنَا الْإِسْلَامِيَّةِ. لِنَنْشُرِ الْمَحَبَّةَ وَالسَّلَامَ بَيْنَ بَنِي الْبَشَرِ.", tr: "Khutbah 2: Di tengah masyarakat kita yang beragam, kita wajib menampilkan wajah Islam yang toleran dan hidup damai dengan semua manusia, tanpa mengorbankan akidah dan identitas keislaman kita. Mari sebarkan kasih sayang dan perdamaian di antara umat manusia." }
      ]
    },
    {
      judul: "3. Kesehatan Mental dan Ketakwaan",
      isi: [
        { ar: "أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ. إِنَّ ضُغُوطَاتِ الْحَيَاةِ الْحَدِيْثَةِ قَدْ تُسَبِّبُ الْقَلَقَ وَالِاكْتِئَابَ لِبَعْضِنَا، وَدِيْنُنَا يُعَلِّمُنَا أَنَّ الطُّمَأْنِيْنَةَ تَكُوْنُ بِذِكْرِ اللَّهِ وَالصَّلَاةِ وَالْقُرْآنِ.", tr: "Khutbah 1: Ingatlah, hanya dengan mengingat Allah hati menjadi tenang. Tekanan hidup modern terkadang menyebabkan kecemasan dan depresi bagi sebagian kita. Agama kita mengajarkan bahwa ketenangan sejati hanya didapat dengan dzikir, salat, dan membaca Al-Qur'an." },
        { ar: "فَلَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا. عَلَيْنَا أَنْ نَتَوَاكَلَ عَلَى اللَّهِ وَنَطْلُبَ الْمَسَاعَدَةَ إِذَا لَزِمَ الْأَمْرُ، فَإِنَّ الْإِسْلَامَ يَحُثُّ عَلَى الْعِنَايَةِ بِصِحَّةِ الْجَسَدِ وَالْعَقْلِ وَالنَّفْسِ.", tr: "Khutbah 2: Janganlah engkau bersedih, sesungguhnya Allah bersama kita. Kita harus bertawakal kepada Allah dan mencari bantuan jika memang diperlukan. Islam sangat mendorong kita untuk menjaga kesehatan fisik, akal, dan juga mental/jiwa." }
      ]
    },
    {
      judul: "4. Menghindari Perilaku Flexing dan Boros",
      isi: [
        { ar: "وَلَا تُسْرِفُوْا إِنَّهُ لَا يُحِبُّ الْمُسْرِفِيْنَ. إِنَّ ظَاهِرَةَ التَّفَاخُرِ بِالْأَمْوَالِ وَالْمَرْكَبَاتِ وَالْمَلَابِسِ فِي الْعِيْدِ تُخَالِفُ تَعَالِيْمَ الْإِسْلَامِ الَّتِي تَدْعُوْ إِلَى الْقَنَاعَةِ وَالزُّهْدِ.", tr: "Khutbah 1: Dan janganlah kamu berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan. Fenomena pamer kekayaan, kendaraan, dan pakaian baru saat hari raya sangat bertentangan dengan ajaran Islam yang mengajarkan sikap qana'ah (merasa cukup) dan zuhud." },
        { ar: "تَذَكَّرُوْا إِخْوَانَكُمُ الْفُقَرَاءَ وَالْيَتَامَى فِي يَوْمِ الْعِيْدِ. الْعِيْدُ لَيْسَ لِلْمُبَاهَاةِ، بَلْ لِلْمُشَارَكَةِ وَالتَّضَامُنِ الْاجْتِمَاعِيِّ. أَنْفِقُوْا مِنْ أَمْوَالِكُمْ فِي سَبِيْلِ اللَّهِ وَلَا تُلْقُوْا بِأَيْدِيْكُمْ إِلَى التَّهْلُكَةِ.", tr: "Khutbah 2: Ingatlah saudara-saudara kita yang fakir dan anak yatim di hari raya ini. Hari raya bukanlah untuk saling membangga-banggakan diri, melainkan untuk berbagi dan solidaritas sosial. Infakkanlah hartamu di jalan Allah." }
      ]
    },
    {
      judul: "5. Mendidik Anak di Era Digital",
      isi: [
        { ar: "يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ. فِي زَمَنِنَا هَذَا، الْجَوَالِكُ وَالْإِنْتَرْنِتُ سِلَاحٌ ذُو حَدَّيْنِ. عَلَيْنَا أَنْ نُرَاقِبَ أَوْلَادَنَا وَنُوَجِّهَهُمْ لِاسْتِخْدَامِ التِّكْنُوْلُوْجِيَا فِي الْخَيْرِ.", tr: "Khutbah 1: Wahai orang-orang yang beriman, peliharalah dirimu dan keluargamu dari api neraka. Di zaman ini, gadget dan internet adalah pisau bermata dua. Kita wajib mengawasi anak-anak kita dan mengarahkan mereka menggunakan teknologi untuk kebaikan." },
        { ar: "الْأَطْفَالُ أَمَانَةٌ فِي أَعْنَاقِنَا. خَصِّصْ وَقْتًا لِلَّعِبِ مَعَهُمْ وَالتَّوَاصُلِ الْمُبَاشِرِ بَدَلًا مِنَ الْغَرَقِ فِي الْشَّاشَاتِ. عَلِّمُوهُمُ الْقُرْآنَ وَالْأَدَبَ وَالْأَخْلَاقَ الْكَرِيْمَةَ لِيَكُوْنُوْا جِيْلًا صَالِحًا يَخْدُمُ الدِّيْنَ وَالْوَطَنَ.", tr: "Khutbah 2: Anak-anak adalah amanah di pundak kita. Luangkan waktu untuk bermain dan berkomunikasi langsung dengan mereka, alih-alih tenggelam dalam layar. Ajarkan mereka Al-Qur'an, adab, dan akhlak mulia agar menjadi generasi saleh yang berguna bagi agama dan bangsa." }
      ]
    },
    {
      judul: "6. Ekonomi Umat Pasca Lebaran",
      isi: [
        { ar: "وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا. بَعْدَ عِيْدِ الْفِطْرِ، نَعُوْدُ إِلَى مَيْدَانِ الْعَمَلِ وَالْكَسْبِ. لِنَبْتَعِدْ عَنِ الِاسْتِهْلَاكِ الْمُفْرِطِ وَالْقُرُوْضِ الرِّبَوِيَّةِ الَّتِي تُدَمِّرُ الِاقْتِصَادَ.", tr: "Khutbah 1: Allah menghalalkan jual beli dan mengharamkan riba. Setelah Idul Fitri, kita kembali ke medan kerja dan mencari rezeki. Mari menjauhi perilaku konsumtif berlebihan dan utang berbasis riba yang dapat menghancurkan ekonomi keluarga." },
        { ar: "إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ. لِنَدْعَمْ الِاقْتِصَادَ الْإِسْلَامِيَّ بِالتَّعَاوُنِ وَالْمُشَارَكَةِ. مَنْ كَانَ لَهُ فَضْلُ مَالٍ فَلْيُعِنْ إِخْوَانَهُ الَّذِيْنَ لَا يَجِدُوْنَ سَبِيْلًا لِلْعَمَلِ لِيَبْدَأُوْا مَشْرُوْعًا صَغِيْرًا يَعُوْلُ أُسْرَتَهُمْ.", tr: "Khutbah 2: Sesungguhnya Allah mencintai orang-orang yang berbuat kebajikan. Mari dukung ekonomi Islam dengan tolong-menolong dan berbagi. Barangsiapa memiliki kelebihan harta, hendaklah membantu saudaranya yang belum mendapat pekerjaan agar bisa memulai usaha kecil untuk menopang keluarganya." }
      ]
    },
    {
      judul: "7. Memperkuat Ukhuwah Islamiyah",
      isi: [
        { ar: "إِنَّمَا الْمُؤْمِنُوْنَ إِخْوَةٌ فَأَصْلِحُوْا بَيْنَ أَخَوَيْكُمْ. الِاخْتِلَافُ فِي الْمَسَائِلِ الْفُرُوْعِيَّةِ هُوَ أَمْرٌ طَبِيْعِيٌّ، وَلَكِنَّهُ لَا يَنْبَغِيْ أَنْ يَكُوْنَ سَبَبًا لِلْفُرْقَةِ وَالْعَدَاوَةِ بَيْنَ الْمُسْلِمِيْنَ.", tr: "Khutbah 1: Sesungguhnya orang-orang mukmin itu bersaudara, maka damaikanlah antara kedua saudaramu. Perbedaan pendapat dalam masalah furu'iyah (cabang ibadah) adalah hal yang wajar, tetapi tidak boleh menjadi penyebab perpecahan dan permusuhan di antara umat Islam." },
        { ar: "يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوْبًا وَقَبَائِلَ لِتَعَارَفُوْا. لِنَجْعَلْ هَذَا الْعِيْدَ فُرْصَةً لِنَبْذِ الْأَحْقَادِ وَالضَّغَائِنِ، وَلِنَتَوَاصَلْ وَنَتَحَابَّ فِيْمَا بَيْنَنَا.", tr: "Khutbah 2: Hai manusia, sesungguhnya Kami menciptakan kamu dari seorang laki-laki dan seorang perempuan dan menjadikan kamu berbangsa-bangsa dan bersuku-suku supaya kamu saling kenal-mengenal. Mari jadikan hari raya ini momentum untuk membuang rasa dendam dan kebencian, serta saling menyambung tali kasih sayang." }
      ]
    },
    {
      judul: "8. Menjaga Lingkungan Hidup",
      isi: [
        { ar: "وَلَا تُفْسِدُوْا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا. إِنَّ مُشْكِلَةَ النِّفَايَاتِ الْبَلَاسْتِيْكِيَّةِ وَتَغَيُّرِ الْمُنَاخِ هِيَ تَحَدٍّ كَبِيْرٌ فِي عَصْرِنَا. الْإِسْلَامُ يَأْمُرُنَا بِالنَّظَافَةِ وَالْمُحَافَظَةِ عَلَى الْبِيْئَةِ.", tr: "Khutbah 1: Dan janganlah kamu membuat kerusakan di muka bumi sesudah (Allah) memperbaikinya. Masalah sampah plastik dan perubahan iklim adalah tantangan besar di era kita. Islam memerintahkan kita untuk menjaga kebersihan dan melestarikan lingkungan hidup." },
        { ar: "النَّظَافَةُ مِنَ الْإِيْمَانِ. خُصُوْصًا فِي الْعِيْدِ، لَا تَرْمُوْا الْقُمَامَةَ فِي الشَّوَارِعِ أَوِ الْأَنْهَارِ. رَتِّبُوْا بُيُوْتَكُمْ وَبِيْئَتَكُمْ، فَإِنَّ الْأَرْضَ أَمَانَةٌ مِنَ اللَّهِ لَنَا جَمِيْعًا.", tr: "Khutbah 2: Kebersihan adalah sebagian dari iman. Terutama saat hari raya, jangan membuang sampah ke jalan atau sungai. Rapikan rumah dan lingkungan kalian, karena bumi ini adalah amanah dari Allah untuk kita semua." }
      ]
    },
    {
      judul: "9. Istiqamah Setelah Ramadan",
      isi: [
        { ar: "فَاسْتَقِمْ كَمَا أُمِرْتَ وَمَنْ تَابَ مَعَكَ. عَلَامَةُ قَبُوْلِ عَمَلِ رَمَضَانَ هِيَ الِاسْتِمْرَارُ فِي الطَّاعَةِ بَعْدَهُ. لَا تَتْرُكِ الْقُرْآنَ وَالصَّلَاةَ بَعْدَ أَنْ كُنْتَ مُجْتَهِدًا فِيهِمَا فِي رَمَضَانَ.", tr: "Khutbah 1: Maka tetaplah kamu pada jalan yang benar, sebagaimana diperintahkan kepadamu dan (juga) orang yang telah taubat besamamu. Tanda diterimanya amal Ramadan adalah istiqamah (berkelanjutan) dalam ketaatan setelahnya. Jangan tinggalkan Al-Qur'an dan salat setelah engkau bersungguh-sungguh di bulan Ramadan." },
        { ar: "وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ. جَاهِدْ نَفْسَكَ لِتَكُوْنَ أَفْضَلَ فِي بَقِيَّةِ عُمْرِكَ. الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنَ الْمُؤْمِنِ الضَّعِيْفِ.", tr: "Khutbah 2: Barangsiapa bertakwa kepada Allah niscaya Dia akan mengadakan jalan keluar baginya dan memberinya rezeki dari arah yang tiada disangka-sangka. Perjuangkan jiwamu untuk menjadi lebih baik di sisa hidupmu. Mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah." }
      ]
    },
    {
      judul: "10. Merawat Tradisi dan Budaya Islami",
      isi: [
        { ar: "خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ. إِنَّ تَقَالِيْدَ مُصَافَحَةِ الْأَيْدِي (الْمُصَافَحَةُ) وَالتَّوَاصُلِ بَعْدَ رَمَضَانَ هِيَ مِنَ الْعَادَاتِ الْحَسَنَةِ الَّتِي تَجْمَعُ بَيْنَ الْقُلُوْبِ وَتُذِيْبُ الْأَحْقَادَ.", tr: "Khutbah 1: Sebaik-baik manusia adalah yang paling bermanfaat bagi manusia lainnya. Tradisi bersalaman (sungkeman) dan saling berkunjung setelah Ramadan adalah kebiasaan baik yang dapat menyatukan hati dan meluluhkan rasa dendam." },
        { ar: "لِنُرَافِقْ بَيْنَ الرُّوْحِ الْإِسْلَامِيَّةِ وَبَيْنَ الْأَخْلَاقِ الْأَصِيْلَةِ لِهَذَا الْبَلَدِ. تَشَبَّهُوْا بِأَخْلَاقِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الرَّحْمَةِ وَالتَّسَامُحِ وَنَبْذِ الْعُنْفِ.", tr: "Khutbah 2: Mari kita harmoni-kan nilai-nilai spiritual Islam dengan budaya luhur bangsa ini. Teladanilah akhlak Nabi Muhammad SAW dalam hal kasih sayang, toleransi, dan menjauhi kekerasan." }
      ]
    }
  ]
};

